mapper.select:
SELECT id, name, sort_order AS sortOrder, created_at AS createdAt, updated_at AS updatedAt FROM t_group WHERE deleted_at IS NULL AND user_id = #{criteria.ownerUserId}
AND (created_at, id) < (#{criteria.cursorCreatedAt}, #{criteria.cursorId})
ORDER BY created_at DESC, id DESC LIMIT #{criteria.fetchSize}
